using System;using System.Data.SqlClient;
namespace Training.Manager{public partial class ChangePassword:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();protected void Page_Load(object s,EventArgs e){if(Session["ManagerID"]==null)Response.Redirect("~/Default.aspx");}protected void btnChange_Click(object s,EventArgs e){lblMessage.Text="";if(string.IsNullOrWhiteSpace(txtCurrentPassword.Text)||string.IsNullOrWhiteSpace(txtNewPassword.Text)){lblMessage.Text="Please enter all passwords.";lblMessage.ForeColor=System.Drawing.Color.Red;return;}if(txtNewPassword.Text!=txtConfirmPassword.Text){lblMessage.Text="New Password and Confirm Password do not match.";lblMessage.ForeColor=System.Drawing.Color.Red;return;}if(txtNewPassword.Text.Length<6){lblMessage.Text="New Password must be at least 6 characters.";lblMessage.ForeColor=System.Drawing.Color.Red;return;}string mid=Session["ManagerID"].ToString();object emp=obj.ExecuteScalar("SELECT EmpID FROM ManagerMaster WHERE ManagerID=@ManagerID",new SqlParameter[]{new SqlParameter("@ManagerID",mid)});if(emp==null||emp==DBNull.Value)return;string current=Convert.ToString(obj.ExecuteScalar("SELECT Password FROM Login WHERE CorrespondingEmpID=@EmpID",new SqlParameter[]{new SqlParameter("@EmpID",emp.ToString())}));if(current!=txtCurrentPassword.Text){lblMessage.Text="Current Password is incorrect.";lblMessage.ForeColor=System.Drawing.Color.Red;return;}int n=obj.ExecuteSql("UPDATE Login SET Password=@Password WHERE CorrespondingEmpID=@EmpID",new SqlParameter[]{new SqlParameter("@Password",txtNewPassword.Text),new SqlParameter("@EmpID",emp.ToString())});lblMessage.Text=n>0?"Password changed successfully.":"Password change failed.";lblMessage.ForeColor=n>0?System.Drawing.Color.Green:System.Drawing.Color.Red;}}}